from django.utils.text import slugify


def completeaza_sluguri(apps, schema_editor):
    Categorie = apps.get_model('ceaiuri', 'Categorie')
    categorii = Categorie.objects.using(schema_editor.connection.alias)
    for categorie in categorii.filter(slug__isnull=True).order_by('pk'):
        baza = slugify(categorie.nume)[:100] or 'categorie'
        slug = baza
        sufix = 1
        while categorii.filter(slug=slug).exists():
            slug = f'{baza}-{sufix}'
            sufix += 1
        categorie.slug = slug
        categorie.save(using=schema_editor.connection.alias, update_fields=['slug'])


